#include<stdio.h>
#include<string.h>

int main(){
	char S[1010];
	scanf("%s",S);
	int len=strlen(S);

	if(S[len-1]=='s'){
		printf("%ses",S);
	}else{
		printf("%ss",S);
	}
}
